@Getter
@Setter
public class ProcessingData implements Serializable {
  @Getter
  @Setter
  private static Geometry dataPolyGeom;
  @Getter
  @Setter
  private static double timeout;
  @Getter
  @Setter
  private static int numberOfDataExtractionThreads = 1;
