            mapAgg.count();
      case PERIMETER:
        return (SortedMap<OSHDBCombinedIndex<OSHDBCombinedIndex<Integer, K>, OSHDBTimestamp>, V>)
            mapAggGeom.sum(geom -> {
              if (!(geom instanceof Polygonal)) {
