    } else {
      return NUMBER_OF_CONTRIBUTIONS + AGGREGATED_ON_THE_BOUNDARY;
    }
  }

  private Description() {
    throw new IllegalStateException("Utility class");
  }
}

@Getter
@AllArgsConstructor
@JsonInclude(Include.NON_NULL)
public class Metadata {

