public class ConfigureApplication {

  private enum DatabaseType {
    H2, JDBC, IGNITE, NONE
  }

  private boolean multithreading = true;
  private String dbPrefix = "";
  private long timeoutInMilliseconds = Application.DEFAULT_TIMEOUT_IN_MILLISECONDS;
  private int numberOfClusterNodes = Application.DEFAULT_NUMBER_OF_CLUSTER_NODES;
  private int numberOfDataExtractionThreads = Application.DEFAULT_NUMBER_OF_DATA_EXTRACTION_THREADS;
  private String databaseUser;
  private String databasePassword;
  private DatabaseType databaseType = DatabaseType.NONE;
  private String databaseUrl;
  private String keytablesUser;
  private String keytablesPassword;
  private DatabaseType keytablesType = DatabaseType.NONE;
  private String keytablesUrl;
  private long ttMaxBytesValue = 512L * 1024L * 1024L;
  private int ttMaxNumRoles = Integer.MAX_VALUE;

  private ConfigureApplication(ApplicationArguments args) {
    for (String paramName : args.getOptionNames()) {
      switch (paramName) {
        // TODO change to "database.h2" for a future stable version
        case "database.db":
          databaseType = DatabaseType.H2;
          databaseUrl = args.getOptionValues(paramName).get(0);
          break;
        case "database.jdbc":
          databaseType = DatabaseType.JDBC;
          String[] jdbcParam = args.getOptionValues(paramName).get(0).split(";");
          databaseUrl = jdbcParam[1];
          databaseUser = jdbcParam[2];
          databasePassword = jdbcParam[3];
          break;
        case "database.ignite":
          databaseType = DatabaseType.IGNITE;
          databaseUrl = args.getOptionValues(paramName).get(0);
          break;
        case "database.keytables":
          keytablesType = DatabaseType.H2;
          keytablesUrl = args.getOptionValues(paramName).get(0);
          break;
        case "database.keytables.jdbc":
          keytablesType = DatabaseType.JDBC;
          String[] keytablesJdbcParam = args.getOptionValues(paramName).get(0).split(";");
          keytablesUrl = keytablesJdbcParam[1];
          keytablesUser = keytablesJdbcParam[2];
          keytablesPassword = keytablesJdbcParam[3];
          break;
        case "database.multithreading":
          if (args.getOptionValues(paramName).get(0).equalsIgnoreCase("false")) {
            multithreading = false;
          }
          break;
        case "database.prefix":
          dbPrefix = args.getOptionValues(paramName).get(0);
          break;
        case "database.timeout":
          timeoutInMilliseconds = Long.parseLong(args.getOptionValues(paramName).get(0));
          break;
        case "cluster.servernodes.count":
          numberOfClusterNodes = Integer.parseInt(args.getOptionValues(paramName).get(0));
          break;
        case "cluster.dataextraction.threadcount":
          numberOfDataExtractionThreads = Integer.parseInt(args.getOptionValues(paramName).get(0));
          break;
        case "tt.maxbytesvalue":
          ttMaxBytesValue = Long.parseLong(args.getOptionValues(paramName).get(0));
          break;
        case "tt.maxnumroles":
          ttMaxNumRoles = Integer.parseInt(args.getOptionValues(paramName).get(0));
          break;
        default:
          break;
      }
    }
  }

  /**
   * Method run by the Application class to parse incoming command line arguments.
   *
   * @param args ApplicationArguments from spring to be parsed.
   */
  public static void parseArguments(ApplicationArguments args)
      throws OSHDBKeytablesNotFoundException, IOException {
    var config = new ConfigureApplication(args);
    switch (config.keytablesType) {
      case H2:
        DbConnData.keytablesDbSource = H2Support.createJdbcPoolFromPath(config.keytablesUrl);
        break;
      case JDBC:
        var keytablesHc = new HikariConfig();
        keytablesHc.setJdbcUrl(config.keytablesUrl);
        keytablesHc.setUsername(config.keytablesUser);
        keytablesHc.setPassword(config.keytablesPassword);
        keytablesHc.setMaximumPoolSize(config.numberOfDataExtractionThreads);
        DbConnData.keytablesDbSource = new HikariDataSource(keytablesHc);
        break;
      default:
        break;
    }
    switch (config.databaseType) {
      case H2:
        DbConnData.db = new OSHDBH2(config.databaseUrl);
        break;
      case JDBC:
        var hc = new HikariConfig();
        hc.setJdbcUrl(config.databaseUrl);
        hc.setUsername(config.databaseUser);
        hc.setPassword(config.databasePassword);
        DbConnData.dbSource =  new HikariDataSource(hc);
        DbConnData.db = new OSHDBJdbc(DbConnData.dbSource, config.dbPrefix,
            DbConnData.keytablesDbSource == null ? DbConnData.dbSource
                : DbConnData.keytablesDbSource);
        break;
      case IGNITE:
        if (DbConnData.keytablesDbSource == null) {
          throw new IllegalArgumentException("Keytables parameter missing");
        }
        DbConnData.db = new OSHDBIgnite(config.databaseUrl, config.dbPrefix,
            DbConnData.keytablesDbSource);
        break;
      default:
        throw new IllegalArgumentException(
            "You have to define one of the following three database parameters: '--database.db', "
                + "'--database.ignite', or '--database.jdbc'.");
    }
    ProcessingData.setTimeout(config.timeoutInMilliseconds / 1000.0);
    DbConnData.db.timeoutInMilliseconds(config.timeoutInMilliseconds);
    ProcessingData.setNumberOfClusterNodes(config.numberOfClusterNodes);
    ProcessingData.setNumberOfDataExtractionThreads(config.numberOfDataExtractionThreads);
    if (DbConnData.db instanceof OSHDBJdbc) {
      DbConnData.db = ((OSHDBJdbc) DbConnData.db).multithreading(config.multithreading);
    }

    // initialize TagTranslator
    DbConnData.tagTranslator = new CachedTagTranslator(DbConnData.db.getTagTranslator(),
        config.ttMaxBytesValue, config.ttMaxNumRoles);

    // extract metadata
    RequestUtils.extractOSHDBMetadata();

    if (DbConnData.db instanceof OSHDBIgnite) {
      ((OSHDBIgnite) DbConnData.db).onClose(() -> {
        // TODO add connections to close
      });
    }
  }
}

@RequiredArgsConstructor
public class GeometryBuilder {

  GeometryFactory gf;
  private final ProcessingData processingData;

  public GeometryBuilder() {
    this.processingData = null;
  }

  /**
   * Creates a unified <code>Geometry</code> object out of the content of the given
   * <code>String</code> array.
   *
   * @param bboxes <code>String</code> array containing the lon/lat coordinates of the bounding
   *        boxes. Each bounding box must consist of 2 lon/lat coordinate pairs (bottom-left and
   *        top-right).
   * @return <code>Geometry</code> object representing the unified bounding boxes.
   * @throws BadRequestException if bboxes coordinates are invalid
   */
  public Geometry createBboxes(String[] bboxes) {
    try {
      Geometry unifiedBbox;
      OSHDBBoundingBox bbox;
      gf = new GeometryFactory();
      double minLon = Double.parseDouble(bboxes[0]);
      double minLat = Double.parseDouble(bboxes[1]);
      double maxLon = Double.parseDouble(bboxes[2]);
      double maxLat = Double.parseDouble(bboxes[3]);
      bbox = OSHDBBoundingBox.bboxWgs84Coordinates(minLon, minLat, maxLon, maxLat);
      unifiedBbox = gf.createGeometry(OSHDBGeometryBuilder.getGeometry(bbox));
      ArrayList<Geometry> geometryList = new ArrayList<>();
      geometryList.add(OSHDBGeometryBuilder.getGeometry(bbox));
      for (int i = 4; i < bboxes.length; i += 4) {
        minLon = Double.parseDouble(bboxes[i]);
        minLat = Double.parseDouble(bboxes[i + 1]);
        maxLon = Double.parseDouble(bboxes[i + 2]);
        maxLat = Double.parseDouble(bboxes[i + 3]);
        bbox = OSHDBBoundingBox.bboxWgs84Coordinates(minLon, minLat, maxLon, maxLat);
        geometryList.add(OSHDBGeometryBuilder.getGeometry(bbox));
        unifiedBbox = unifiedBbox.union(OSHDBGeometryBuilder.getGeometry(bbox));
      }
      Geometry result = unifyPolys(geometryList);
      processingData.setBoundaryList(geometryList);
      processingData.setRequestGeom(unifiedBbox);
      return result;
    } catch (NumberFormatException e) {
      throw new BadRequestException(
          "Apart from the custom ids, the bboxeses array must contain double-parseable values "
              + "in the following order: minLon, minLat, maxLon, maxLat.");
    }
  }

  /**
   * Creates a <code>Geometry</code> object around the coordinates of the given <code>String</code>
   * array.
   *
   * @param bpoints <code>String</code> array containing the lon/lat coordinates of the point at [0]
   *        and [1] and the size of the buffer at [2].
   * @return <code>Geometry</code> object representing (a) circular polygon(s) around the given
   *         bounding point(s).
   * @throws BadRequestException if bcircle coordinates or radius are invalid
   */
  public Geometry createCircularPolygons(String[] bpoints) {
    GeometryFactory geomFact = new GeometryFactory();
    Geometry buffer;
    Geometry geom;
    CoordinateReferenceSystem sourceCrs;
    CoordinateReferenceSystem targetCrs;
    MathTransform transform = null;
    ArrayList<Geometry> geometryList = new ArrayList<>();
    InputProcessingUtils utils = new InputProcessingUtils();
    try {
      for (int i = 0; i < bpoints.length; i += 3) {
        sourceCrs = CRS.decode("EPSG:4326", true);
        targetCrs = CRS.decode(
            utils.findEpsg(Double.parseDouble(bpoints[i]), Double.parseDouble(bpoints[i + 1])),
            true);
        transform = CRS.findMathTransform(sourceCrs, targetCrs, false);
        Point p = geomFact.createPoint(
            new Coordinate(Double.parseDouble(bpoints[i]), Double.parseDouble(bpoints[i + 1])));
        buffer = JTS.transform(p, transform).buffer(Double.parseDouble(bpoints[i + 2]));
        transform = CRS.findMathTransform(targetCrs, sourceCrs, false);
        geom = JTS.transform(buffer, transform);
        if (bpoints.length == 3) {
          if (!utils.isWithin(geom)) {
            throw new NotFoundException(ExceptionMessages.BOUNDARY_NOT_IN_DATA_EXTRACT);
          }
          geometryList.add(geom);
          processingData.setBoundaryList(geometryList);
          processingData.setRequestGeom(geom);
          return geom;
        }
        geometryList.add(geom);
      }
      Geometry result = unifyPolys(geometryList);
      processingData.setBoundaryList(geometryList);
      processingData.setRequestGeom(result);
      return result;
    } catch (NumberFormatException | FactoryException | MismatchedDimensionException
        | TransformException | ArrayIndexOutOfBoundsException e) {
      throw new BadRequestException(
          "Each bcircle must consist of a lon/lat coordinate pair plus a buffer in meters.");
    }
  }

  /**
   * Creates a <code>Polygon</code> out of the coordinates in the given array. If more polygons are
   * given, a union of the polygons is applied and a <code>MultiPolygon</code> is created.
   *
   * @param bpolys <code>String</code> array containing the lon/lat coordinates of the bounding
   *        polygon(s).
   * @return <code>Geometry</code> object representing a <code>Polygon</code> object, if only one
   *         polygon was given or a <code>MultiPolygon</code> object, if more than one were given.
   * @throws BadRequestException if bpolys coordinates are invalid
   */
  public Geometry createBpolys(String[] bpolys) {
    GeometryFactory geomFact = new GeometryFactory();
    Geometry bpoly;
    ArrayList<Coordinate> coords = new ArrayList<>();
    ArrayList<Geometry> geometryList = new ArrayList<>();
    InputProcessingUtils utils = new InputProcessingUtils();
    if (bpolys[0].equals(bpolys[bpolys.length - 2])
        && bpolys[1].equals(bpolys[bpolys.length - 1])) {
      try {
        for (int i = 0; i < bpolys.length; i += 2) {
          coords.add(
              new Coordinate(Double.parseDouble(bpolys[i]), Double.parseDouble(bpolys[i + 1])));
        }
        bpoly = geomFact.createPolygon(coords.toArray(new Coordinate[] {}));
      } catch (IllegalArgumentException e) {
        throw new BadRequestException(ExceptionMessages.BPOLYS_FORMAT);
      }
      if (!utils.isWithin(bpoly)) {
        throw new NotFoundException(ExceptionMessages.BOUNDARY_NOT_IN_DATA_EXTRACT);
      }
      geometryList.add(bpoly);
      processingData.setBoundaryList(geometryList);
      processingData.setRequestGeom(bpoly);
      return bpoly;
    }
    Coordinate firstPoint = null;
    try {
      for (int i = 0; i < bpolys.length; i += 2) {
        if (firstPoint != null && firstPoint.x == Double.parseDouble(bpolys[i])
            && firstPoint.y == Double.parseDouble(bpolys[i + 1])) {
          Polygon poly;
          coords.add(
              new Coordinate(Double.parseDouble(bpolys[i]), Double.parseDouble(bpolys[i + 1])));
          poly = geomFact.createPolygon(coords.toArray(new Coordinate[] {}));
          geometryList.add(poly);
          coords.clear();
          firstPoint = null;
        } else {
          Coordinate coord =
              new Coordinate(Double.parseDouble(bpolys[i]), Double.parseDouble(bpolys[i + 1]));
          coords.add(coord);
          if (firstPoint == null) {
            firstPoint = coord;
          }
        }
      }
      Geometry result = unifyPolys(geometryList);
      processingData.setBoundaryList(geometryList);
      processingData.setRequestGeom(result);
      return result;
    } catch (NumberFormatException | MismatchedDimensionException e) {
      throw new BadRequestException(ExceptionMessages.BPOLYS_FORMAT);
    }
  }

  /**
   * Creates a Geometry object from the given GeoJSON String, which is derived from the metadata.
   *
   * @throws RuntimeException if the derived GeoJSON cannot be converted to a Geometry
   */
  public void createGeometryFromMetadataGeoJson(String geoJson) {
    GeoJSONReader reader = new GeoJSONReader();
    try {
      ProcessingData.setDataPolyGeom(reader.read(geoJson));
    } catch (Exception e) {
      throw new RuntimeException("The GeoJSON that is derived out of the metadata, cannot be "
          + "converted. Please use a different data file and contact an admin about this issue.");
    }
  }

  /**
   * Creates a Geometry object from the given GeoJSON String. It must be of type 'FeatureCollection'
   * and its features must be of type 'Polygon' or 'Multipolygon'.
   *
   * @throws BadRequestException if the given GeoJSON String cannot be converted to a Geometry, it
   *         is not of the type 'FeatureCollection', or if the provided custom id(s) cannot be
   *         parsed
   */
  public Geometry createGeometryFromGeoJson(String geoJson, InputProcessor inputProcessor) {
    ArrayList<Geometry> geometryList = new ArrayList<>();
    JsonObject root = null;
    JsonArray features;
    Serializable[] boundaryIds;
    GeoJsonObject[] geoJsonGeoms;
    try (JsonReader jsonReader = Json.createReader(new StringReader(geoJson))) {
      root = jsonReader.readObject();
      features = root.getJsonArray("features");
      boundaryIds = new Serializable[features.size()];
      geoJsonGeoms = new GeoJsonObject[features.size()];
    } catch (Exception e) {
      throw new BadRequestException("Error in reading the provided GeoJSON. The given GeoJSON has "
          + "to be of the type 'FeatureCollection'. Please take a look at the documentation page "
          + "for the bpolys parameter to see an example of a fitting GeoJSON input file.");
    }
    int count = 0;
    for (JsonValue featureVal : features) {
      JsonObject feature = featureVal.asJsonObject();
      JsonObject properties = feature.getJsonObject("properties");
      try {
        if (feature.containsKey("id")) {
          boundaryIds[count] = createBoundaryIdFromJsonObjectId(feature, inputProcessor);
        } else if (properties != null && properties.containsKey("id")) {
          boundaryIds[count] = createBoundaryIdFromJsonObjectId(properties, inputProcessor);
        } else {
          boundaryIds[count] = "feature" + (count + 1);
        }
        count++;
      } catch (BadRequestException e) {
        throw e;
      } catch (Exception e) {
        throw new BadRequestException("The provided custom id(s) could not be parsed.");
      }
      try {
        JsonObject geomObj = feature.getJsonObject("geometry");
        checkGeometryTypeOfFeature(geomObj);
        GeoJSONReader reader = new GeoJSONReader();
        Geometry currentResult = reader.read(geomObj.toString());
        geometryList.add(currentResult);
        geoJsonGeoms[count - 1] =
            new ObjectMapper().readValue(geomObj.toString(), GeoJsonObject.class);
      } catch (Exception e) {
        throw new BadRequestException("The provided GeoJSON cannot be converted. Please take a "
            + "look at the documentation page for the bpolys parameter to see an example of a "
            + "fitting GeoJSON input file.");
      }
    }
    Geometry result = unifyPolys(geometryList);
    processingData.setGeoJsonGeoms(geoJsonGeoms);
    processingData.setBoundaryList(geometryList);
    processingData.setRequestGeom(result);
    InputProcessingUtils util = inputProcessor.getUtils();
    util.setBoundaryIds(boundaryIds);
    return result;
  }

  /**
   * Computes the union of the given geometries and checks if it is completely within the underlying
   * data extract.
   *
   * @param geometries <code>Collection</code> containing the geometries to unify
   * @return unified geometries
   * @throws NotFoundException if the unified Geometry does not lie completely within the underlying
   *         data extract
   */
  private Geometry unifyPolys(Collection<Geometry> geometries) {
    GeometryFactory geometryFactory = new GeometryFactory();
    Polygon[] polys = geometries.stream().flatMap(geo -> {
      if (geo instanceof MultiPolygon) {
        int num = geo.getNumGeometries();
        ArrayList<Polygon> parts = new ArrayList<>(num);
        for (int i = 0; i < num; i++) {
          parts.add((Polygon) geo.getGeometryN(i));
        }
        return parts.stream();
      } else {
        return Stream.of(geo);
      }
    }).toArray(Polygon[]::new);
    MultiPolygon mp = geometryFactory.createMultiPolygon(polys);
    // merge all input geometries to single (multi) polygon
    Geometry result = mp.union();
    InputProcessingUtils utils = new InputProcessingUtils();
    if (!utils.isWithin(result)) {
      throw new NotFoundException(ExceptionMessages.BOUNDARY_NOT_IN_DATA_EXTRACT);
    }
    return result;
  }

  /**
   * Creates a boundary ID value from the 'id' field in the given <code>JsonObject</code>.
   *
   * @param jsonObject <code>JsonObject</code> where the 'id' value is extracted from
   * @param inputProcessor used for {@link
   *        org.heigit.ohsome.ohsomeapi.inputprocessing.InputProcessingUtils
   *        #checkCustomBoundaryId(String) checkCustomBoundaryId}
   * @return <code>Object</code> having the custom id of type <code>String</code> or
   *         <code>Integer</code>
   */
  private Serializable createBoundaryIdFromJsonObjectId(JsonObject jsonObject,
      InputProcessor inputProcessor) {
    if (jsonObject.get("id").getValueType().compareTo(JsonValue.ValueType.STRING) == 0) {
      String id = jsonObject.getString("id");
      if ("csv".equalsIgnoreCase(processingData.getFormat())) {
        inputProcessor.getUtils().checkCustomBoundaryId(id);
      }
      return id;
    } else {
      return jsonObject.getInt("id");
    }
  }

  /**
   * Checks the geometry of the given <code>JsonObject</code> on its type. If it's not of type
   * Polygon or Multipolygon, an exception is thrown.
   *
   * @param geomObj <code>JsonObject</code> to check
   * @throws BadRequestException if the given <code>JsonObject</code> is not of type Polygon or
   *         Multipolygon
   */
  private void checkGeometryTypeOfFeature(JsonObject geomObj) {
    if (!geomObj.getString("type").equals("Polygon")
        && !geomObj.getString("type").equals("MultiPolygon")) {
      throw new BadRequestException(
          "The geometry of each feature in the GeoJSON has to be of type 'Polygon' "
              + "or 'MultiPolygon'.");
    }
  }

  public ProcessingData getprocessingData() {
    return processingData;
  }

}

